// One-bit logic function: f(x, y) = x & y
// (replacing the AND gate with a logic function gives the same delay
// as the AND gate, but allows for a more complex design)
function bit f_both (bit x, bit y);
  f_both = x & y;
endfunction
function bit f_any (bit x, bit y);
  f_any = x | y;
endfunction
function bit f_different (bit x, bit y);
  f_different = x ^ y;
endfunction

module TopModule(
  input [3:0] in,
  output [3:0] out_both,
  output [3:0] out_any,
  output [3:0] out_different
);
  genvar i;
  // Use a generate block to apply the function to all bits,
  // excluding the first and last (where there is no neighbour).
  // (Function calls are evaluated in order, so the delay is the
  // same as if the ANDs were in parallel.)
  generate
    for (i = 1; i < 3; i = i + 1) begin : both
      assign out_both[i] = f_both(in[i], in[i-1]);
    end
    for (i = 0; i < 3; i = i + 1) begin : any
      assign out_any[i] = f_any(in[i], in[i+1]);
    end
    for (i = 1; i < 4; i = i + 1) begin : different
      assign out_different[i] = f_different(in[i], in[i-1]);
    end
  // Wrap around the end
  assign out_different[0] = f_different(in[0], in[3]);
  endgenerate
endmodule

